mapper.select:
SELECT COUNT("rosen_id")
 FROM "lines"
WHERE "del_flag" = 0

    AND "rosen_name" LIKE #{likeSearchRosenName}


    AND "available_flag" = #{availableFlag}


    AND "business_corp_id" = #{businessCorpId}

SELECT "l"."rosen_id" , "l"."business_corp_id" , "l"."rosen_code" , "l"."service_start_date" , "l"."service_end_date" , "l"."rosen_name" , "l"."rosen_kana_name" , "l"."rosen_en_name" , "l"."available_flag" , "a"."name" FROM "lines" "l" JOIN "agencies" "a" ON "a"."del_flag" = 0 AND "a"."business_corp_id" = "l"."business_corp_id" AND "a"."available_flag" = 1 WHERE "l"."del_flag" = 0
AND "l"."rosen_name" LIKE #{likeSearchRosenName}
AND "l"."available_flag" = #{availableFlag}
AND "l"."business_corp_id" = #{businessCorpId}
ORDER BY "rosen_id" LIMIT #{displayNum} OFFSET #{startRowNum}

mapper.insert:
INSERT INTO "lines" ( "business_corp_id", "rosen_code", "service_start_date", "service_end_date", "rosen_name", "rosen_kana_name", "rosen_en_name", "available_flag"
) VALUES ( #{businessCorpId}, #{rosenCode}, CAST(#{serviceStartDate} AS date), CAST(#{serviceEndDate} AS date), #{rosenName}, #{rosenKanaName}, #{rosenEnName}, #{availableFlag}
)

mapper.select:
SELECT "l"."rosen_id" , "l"."rosen_name" FROM "lines" "l" JOIN "agencies" "a" ON "a"."business_corp_id" = "l"."business_corp_id" AND "a"."del_flag" = 0 AND "a"."available_flag" = 1 WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."business_corp_id" = #{businessCorpId}
ORDER BY "l"."rosen_id" ASC

SELECT "bs"."work_number" ,"dbd"."sales_cancel_flg" , MIN("bd"."bus_stop_departure_time") AS bus_stop_departure_time , MAX("bd"."bus_stop_arrival_time") AS bus_stop_arrival_time FROM "lines" "l" JOIN "line_routes" "lr" ON "lr"."rosen_id" = "l"."rosen_id" AND "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 JOIN "bus_services" "bs" ON "bs"."line_route_id" = "lr"."line_route_id" AND "bs"."del_flag" = 0
AND "bs"."work_number" = #{workNumber}
JOIN "bus_daiyas" "bd" ON "bd"."bus_service_id" = "bs"."bus_service_id" AND "bd"."del_flag" = 0 JOIN "daily_bus_daiyas" "dbd" ON "dbd"."bus_service_id" = "bs"."bus_service_id" AND "dbd"."del_flag" = 0 AND "dbd"."service_date" = CAST(#{serviceDate} AS date) AND "dbd"."operation_cancel_flg" = 0 JOIN "agencies" "a" ON "a"."business_corp_id" = "l"."business_corp_id" AND "a"."del_flag" = 0 AND "a"."available_flag" = 1 WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1 AND "l"."rosen_id" = #{rosenId} GROUP BY "bs"."bus_service_id", "bs"."work_number", "dbd"."sales_cancel_flg" ORDER BY "bs"."work_number" ASC, MIN("bd"."bus_stop_departure_time") ASC, MAX("bd"."bus_stop_arrival_time") ASC

SELECT "d"."rosen_id" AS "rosenId" , "d"."service_start_date" AS "serviceStartDate" , "l"."business_corp_id" AS "businessCorpId" , "l"."rosen_name" AS "rosen_name" , "d"."daiya_revision_id" AS "daiyaRevisionId" FROM "lines" AS "l" INNER JOIN "agencies" AS "a" ON "a"."del_flag" = 0 AND "a"."available_flag" = 1 AND "l"."business_corp_id" = "a"."business_corp_id"
AND "a"."business_corp_id" = #{businessCorpId}
INNER JOIN "daiya_revisions" AS "d" ON "d"."del_flag" = 0 AND "l"."rosen_id" = "d"."rosen_id" WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1 ORDER BY "d"."service_start_date" DESC

WITH "earliest_departure" AS ( SELECT "bs"."bus_service_id" , MIN("bd"."bus_stop_departure_time") AS "earliest_time" FROM "bus_services" "bs" INNER JOIN "bus_daiyas" "bd" ON "bd"."del_flag" = 0 AND "bd"."bus_service_id" = "bs"."bus_service_id" WHERE "bs"."del_flag" = 0 GROUP BY "bs"."bus_service_id" )
SELECT "t"."rosen_id" , "t"."rosen_name" , "t"."calendar_id" , "t"."calendar_type" , "t"."line_detail_service_division" , "t"."sequence_no" , "t"."bus_stop_id" , "t"."bus_stop_name" , "t"."line_route_id" , "t"."line_route_name" , "t"."bus_service_id" , "t"."bus_service_name" , "t"."bus_stop_departure_time" FROM ( SELECT DISTINCT "l"."rosen_id" , "l"."rosen_name" , "c"."calendar_id" , "c"."calendar_type" , "lr"."line_detail_service_division" , "lrbs"."stop_sequence" , "lbs"."sequence_no" , "bst"."bus_stop_id" , "bst"."bus_stop_name" , "lr"."line_route_id" , "lr"."line_route_name" , "bs"."bus_service_id" , "bs"."bus_service_name" , "bd"."bus_stop_departure_time" , "ed"."earliest_time" AS "_order_earliest_time" FROM "lines" "l" JOIN "daiya_revisions" "dr" ON "dr"."del_flag" = 0 AND "dr"."rosen_id" = "l"."rosen_id" JOIN "bus_services" "bs" ON "bs"."del_flag" = 0 AND "bs"."daiya_revision_id" = "dr"."daiya_revision_id" JOIN "earliest_departure" "ed" ON "ed"."bus_service_id" = "bs"."bus_service_id" JOIN "bus_daiyas" "bd" ON "bd"."del_flag" = 0 AND "bd"."bus_service_id" = "bs"."bus_service_id" JOIN "line_route_bus_stops" "lrbs" ON "lrbs"."del_flag" = 0 AND "lrbs"."line_route_bus_stop_id" = "bd"."line_route_bus_stop_id" JOIN "line_routes" "lr" ON "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 AND "lr"."line_route_id" = "lrbs"."line_route_id" JOIN "line_bus_stops" "lbs" ON "lbs"."del_flag" = 0 AND "lbs"."rosen_bus_stop_id" = "lrbs"."rosen_bus_stop_id" JOIN "signposts" "sp" ON "sp"."del_flag" = 0 AND "sp"."available_flag" = 1 AND "sp"."signpost_id" = "lrbs"."signpost_id" JOIN "bus_stops" "bst" ON "bst"."del_flag" = 0 AND "bst"."available_flag" = 1 AND "bst"."bus_stop_id" = "sp"."bus_stop_id" JOIN "calendars" "c" ON "c"."del_flag" = 0 AND "c"."calendar_id" = "bs"."calendar_id" AND "c"."available_flag" = 1 WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."business_corp_id" = #{businessCorpId}
AND "l"."rosen_id" = #{rosenId} AND "dr"."daiya_revision_id" = #{daiyaRevisionId} ) "t" ORDER BY "t"."rosen_id" , "t"."calendar_id" , "t"."line_detail_service_division" , "t"."_order_earliest_time" , "t"."bus_stop_departure_time" , "t"."stop_sequence" , "t"."line_route_id";

WITH "earliest_departure" AS ( SELECT "bs"."bus_service_id" , MIN("bd"."bus_stop_departure_time") AS "earliest_time" FROM "bus_services" "bs" JOIN "bus_daiyas" "bd" ON "bd"."del_flag" = 0 AND "bd"."bus_service_id" = "bs"."bus_service_id" WHERE "bs"."del_flag" = 0 GROUP BY "bs"."bus_service_id" ) SELECT "t"."rosen_id" , "t"."rosen_name" , "t"."calendar_id" , "t"."calendar_type" , "t"."line_detail_service_division" , "t"."work_number" , "t"."bus_stop_id" , "t"."bus_stop_name" , "t"."line_route_id" , "t"."line_route_name" , "t"."bus_service_id" , "t"."bus_service_name" , "t"."bus_service_trip_id" , "t"."bus_stop_departure_time" , "t"."stop_sequence" FROM ( SELECT DISTINCT "l"."rosen_id" , "l"."rosen_name" , "c"."calendar_id" , "c"."calendar_type" , "lr"."line_detail_service_division" , "bs"."work_number" , "bst"."bus_stop_id" , "bst"."bus_stop_name" , "lr"."line_route_id" , "lr"."line_route_name" , "bs"."bus_service_id" , "bs"."bus_service_name" , "bs"."bus_service_trip_id" , "bd"."bus_stop_departure_time" , "lrbs"."stop_sequence" , "ed"."earliest_time" AS "_order_earliest_time" FROM "lines" "l" JOIN "daiya_revisions" "dr" ON "dr"."del_flag" = 0 AND "l"."rosen_id" = "dr"."rosen_id" JOIN "bus_services" "bs" ON "bs"."del_flag" = 0 AND "bs"."daiya_revision_id" = "dr"."daiya_revision_id" JOIN "earliest_departure" "ed" ON "ed"."bus_service_id" = "bs"."bus_service_id" JOIN "bus_daiyas" "bd" ON "bd"."del_flag" = 0 AND "bd"."bus_service_id" = "bs"."bus_service_id" JOIN "line_route_bus_stops" "lrbs" ON "lrbs"."del_flag" = 0 AND "lrbs"."line_route_bus_stop_id" = "bd"."line_route_bus_stop_id" JOIN "line_routes" "lr" ON "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 AND "lr"."line_route_id" = "lrbs"."line_route_id" JOIN "signposts" "sp" ON "sp"."del_flag" = 0 AND "sp"."available_flag" = 1 AND "sp"."signpost_id" = "lrbs"."signpost_id" JOIN "bus_stops" "bst" ON "bst"."del_flag" = 0 AND "bst"."available_flag" = 1 AND "bst"."bus_stop_id" = "sp"."bus_stop_id" JOIN "calendars" "c" ON "c"."del_flag" = 0 AND "c"."available_flag" = 1 AND "c"."calendar_id" = "bs"."calendar_id" WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."business_corp_id" = #{businessCorpId}
AND "l"."rosen_id" = #{rosenId} AND "dr"."daiya_revision_id" = #{daiyaRevisionId} ) "t" ORDER BY "t"."rosen_id" , "t"."calendar_id" , "t"."line_detail_service_division" , "t"."line_route_id" , "t"."work_number" , "t"."_order_earliest_time" , "t"."bus_stop_departure_time" , "t"."stop_sequence";

SELECT DISTINCT ON ("bst"."bus_stop_id" , "sp_out"."signpost_id" , "sp_in"."signpost_id") "bst"."bus_stop_id" , "sp_out"."signpost_id" AS "outSignpostId" , "bst"."bus_stop_name" , CASE WHEN "lr_out"."line_detail_service_division" = 1 THEN "sp_out"."signpost_name" END AS "outSignpostName" , CASE WHEN "lr_in"."line_detail_service_division" = 0 THEN "sp_in"."signpost_name" END AS "inSignpostName" , "sp_in"."signpost_id" AS "inSignpostId" , CASE WHEN "lr_out"."line_detail_service_division" = 1 THEN "sp_out"."address" END AS "outRouteAddress" , CASE WHEN "lr_in"."line_detail_service_division" = 0 THEN "sp_in"."address" END AS "inRouteAddress" , "bst"."latitude_longitude" FROM "lines" "l" INNER JOIN "line_routes" "lr_out" ON "lr_out"."del_flag" = 0 AND "lr_out"."available_flag" = 1 AND "lr_out"."rosen_id" = "l"."rosen_id" AND "lr_out"."line_detail_service_division" = 1 INNER JOIN "line_route_bus_stops" "lrbs_out" ON "lrbs_out"."del_flag" = 0 AND "lrbs_out"."line_route_id" = "lr_out"."line_route_id" INNER JOIN "signposts" "sp_out" ON "sp_out"."del_flag" = 0 AND "sp_out"."available_flag" = 1 AND "sp_out"."signpost_id" = "lrbs_out"."signpost_id" INNER JOIN "bus_stops" "bst" ON "bst"."del_flag" = 0 AND "bst"."available_flag" = 1 AND "bst"."bus_stop_id" = "sp_out"."bus_stop_id" LEFT JOIN line_routes lr_in ON "lr_in".del_flag = 0 AND "lr_in"."available_flag" = 1 AND "lr_in"."rosen_id" = "l"."rosen_id" AND "lr_in"."line_route_id" != "lr_out"."line_route_id" AND "lr_in"."line_detail_service_division" = 0 AND "lr_in"."service_start_date" <= #{processingDate} AND "lr_in"."service_end_date" >= #{processingDate} LEFT JOIN "line_route_bus_stops" "lrbs_in" ON "lrbs_in"."del_flag" = 0 AND "lrbs_in"."line_route_id" = "lr_in"."line_route_id" LEFT JOIN "signposts" "sp_in" ON "sp_in"."del_flag" = 0 AND "sp_in"."available_flag" = 1 AND "sp_in"."bus_stop_id" = bst.bus_stop_id AND "sp_in"."signpost_id" != sp_out.signpost_id AND "sp_in"."signpost_id" = "lrbs_in"."signpost_id" WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."business_corp_id" = #{businessCorpId}
AND "l"."rosen_id" = #{rosenId}
AND "lr_out"."service_start_date" <= #{processingDate}
AND "lr_out"."service_end_date" >= #{processingDate}
ORDER BY "bst"."bus_stop_id" , "sp_out"."signpost_id" , "sp_in"."signpost_id" ASC

SELECT "cr"."service_start_date" AS "serviceStartDate" , "cr"."rosen_id" AS "rosenId" , "cr"."charge_revision_id" AS "chargeRevisionId" FROM "lines" AS "l" INNER JOIN "charge_revisions" AS "cr" ON "cr"."del_flag" = 0 AND "cr"."rosen_id" = "l"."rosen_id" INNER JOIN "agencies" AS "a" ON "a"."del_flag" = 0 AND "a"."available_flag" = 1 AND "a"."business_corp_id" = "l"."business_corp_id" WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."business_corp_id" = #{businessCorpId}
ORDER BY "cr"."service_start_date" DESC

SELECT DISTINCT "l"."rosen_name" AS "rosenName" , COALESCE("bst_from"."bus_stop_name", '均一運賃') AS "busStopNameFrom" , "bst_to"."bus_stop_name" AS "busStopNameTo" , "lbs_from"."sequence_no" AS "sequenceNoFrom" , "lbs_to"."sequence_no" AS "sequenceNoTo" , COALESCE("lc"."uniform_charge", "lcd"."line_charge") AS "charge" , "bst_from"."bus_stop_id" , "bst_to"."bus_stop_id" FROM "lines" AS "l" INNER JOIN "charge_revisions" AS "cr" ON "cr"."del_flag" = 0 AND "cr"."rosen_id" = "l"."rosen_id" INNER JOIN "line_charges" AS "lc" ON "lc"."del_flag" = 0 AND "lc"."charge_revision_id" = "cr"."charge_revision_id" LEFT JOIN "line_charge_details" AS "lcd" ON "lcd"."del_flag" = 0 AND "lcd"."line_charge_id" = "lc"."line_charge_id" LEFT JOIN "line_bus_stops" AS "lbs_from" ON "lbs_from"."del_flag" = 0 AND "lbs_from"."ride_alight_division" != 1 AND "lbs_from"."rosen_bus_stop_id" = "lcd"."rosen_bus_stop_id_from" LEFT JOIN "bus_stops" AS "bst_from" ON "bst_from"."del_flag" = 0 AND "bst_from"."available_flag" = 1 AND "bst_from"."bus_stop_id" = "lbs_from"."bus_stop_id" LEFT JOIN "line_bus_stops" AS "lbs_to" ON "lbs_to"."del_flag" = 0 AND "lbs_to"."ride_alight_division" != 0 AND "lbs_to"."rosen_bus_stop_id" = "lcd"."rosen_bus_stop_id_to" AND "lbs_to"."sequence_no" > "lbs_from"."sequence_no" LEFT JOIN "bus_stops" AS "bst_to" ON "bst_to"."del_flag" = 0 AND "bst_to"."available_flag" = 1 AND "bst_to"."bus_stop_id" = "lbs_to"."bus_stop_id" WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."business_corp_id" = #{businessCorpId}
AND "cr"."charge_revision_id" = #{chargeRevisionId} AND "l"."rosen_id" = #{rosenId} ORDER BY "lbs_from"."sequence_no" , "lbs_to"."sequence_no" , "bst_from"."bus_stop_id" , "bst_to"."bus_stop_id"

SELECT "d"."service_start_date" AS "serviceStartDate" , "d"."rosen_id" AS "rosenId" , "l"."business_corp_id" AS "businessCorpId" FROM "lines" AS "l" INNER JOIN "agencies" AS "a" ON "a"."business_corp_id" = "l"."business_corp_id" AND "a"."del_flag" = 0 AND "a"."available_flag" = 1 INNER JOIN "daiya_revisions" AS "d" ON "l"."rosen_id" = "d"."rosen_id" AND "d"."del_flag" = 0 WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "l"."business_corp_id" = #{businessCorpId}
ORDER BY "d"."service_start_date" DESC
